<?php require_once __DIR__.'/_base.php'; $title='Provider Profile'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT p.*,COALESCE(AVG(r.rating),0) rating,COUNT(r.id) reviews FROM providers p LEFT JOIN ratings r ON r.provider_id=p.id WHERE p.id=? AND p.verification_status='Approved' AND p.account_status='Active' GROUP BY p.id");$st->execute([$id]);$p=$st->fetch();if(!$p){http_response_code(404);echo '<div class="alert alert-danger">Provider not found.</div>';return;}$sv=$pdo->prepare('SELECT s.* FROM services s JOIN provider_services ps ON ps.service_id=s.id WHERE ps.provider_id=?');$sv->execute([$id]);$rv=$pdo->prepare('SELECT r.*,u.name user_name FROM ratings r JOIN users u ON u.id=r.user_id WHERE r.provider_id=? ORDER BY r.created_at DESC');$rv->execute([$id]);?><div class="service-card p-4"><div class="d-flex gap-4 align-items-center"><div class="avatar" style="width:90px;height:90px;font-size:2rem"><?=e(strtoupper(substr($p['name'],0,1)))?></div><div><h2><?=e($p['name'])?> <span class="badge text-bg-success">Verified</span></h2><div class="rating fs-5">★ <?=number_format($p['rating'],1)?> / 5 (<?=$p['reviews']?> reviews)</div></div></div><hr><div class="row g-4"><div class="col-md-7"><h5>About</h5><p><?=e($p['bio'])?></p><h5>Services</h5><p><?php foreach($sv->fetchAll() as $s):?><span class="badge text-bg-light border me-1"><?=e($s['service_name'])?></span><?php endforeach;?></p></div><div class="col-md-5"><p><b>Experience:</b> <?=e($p['experience'])?></p><p><b>Availability:</b> <?=e($p['availability'])?></p><p><b>Charges:</b> PKR <?=number_format($p['charges'],2)?></p><p><b>Location:</b> <?=e($p['address'])?></p><a href="booking.php?provider=<?=$p['id']?>" class="btn btn-success btn-lg">Book Now</a></div></div></div><div class="service-card p-4 mt-4"><h4>Reviews</h4><?php foreach($rv->fetchAll() as $r):?><div class="border-bottom py-3"><b><?=e($r['user_name'])?></b> <span class="rating"><?=str_repeat('★',(int)$r['rating'])?></span><p class="mb-0 text-secondary"><?=e($r['review'])?></p></div><?php endforeach;?></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>